{
  "findings": [
    {
      "check_id": "CKV_AWS_56",
      "title": "S3 Bucket Public Access Block: restrict_public_buckets is disabled",
      "resource": "aws_s3_bucket_public_access_block.api_docs",
      "severity": "MEDIUM",
      "explanation": "The 'restrict_public_buckets' setting is explicitly set to false, which allows public bucket policies to be applied. This increases the risk of accidental data exposure if a permissive policy is attached to the bucket."
    }
  ],
  "patched_code": "resource \"aws_s3_bucket_public_access_block\" \"api_docs\" {\n  bucket = aws_s3_bucket.api_docs.id\n  restrict_public_buckets = true\n}",
  "fix_summary": "Changed 'restrict_public_buckets' from false to true in the aws_s3_bucket_public_access_block resource to enforce that no public access policies can be applied to the S3 bucket, aligning with security best practices for preventing unintended public exposure."
}
